(function(){
'use strict';const KEY='study-notebook-options-v1',positions=[['top-left','왼쪽 위'],['top-center','위 중앙'],['top-right','오른쪽 위'],['middle-left','왼쪽 중앙'],['middle-center','화면 중앙'],['middle-right','오른쪽 중앙'],['bottom-left','왼쪽 아래'],['bottom-center','아래 중앙'],['bottom-right','오른쪽 아래']];let settings={finger:true,position:'bottom-center',hidden:false,zoom:1};try{const v=JSON.parse(localStorage.getItem(KEY));if(v){if(typeof v.finger==='boolean')settings.finger=v.finger;if(positions.some(x=>x[0]===v.position))settings.position=v.position;settings.hidden=!!v.hidden;if(v.zoom>=.75&&v.zoom<=2)settings.zoom=v.zoom;}}catch{}
const bar=document.getElementById('notebook-tools'),open=document.createElement('button');open.id='notebook-options';open.type='button';open.textContent='설정';open.setAttribute('aria-label','필기·확대·녹음 설정');bar.insertBefore(open,bar.querySelector('#notebook-status'));
const reveal=document.createElement('button');reveal.id='notebook-reveal';reveal.type='button';reveal.textContent='도구 표시';document.body.append(reveal);
const panel=document.createElement('dialog');panel.id='notebook-settings';panel.innerHTML=`<div class="notebook-dialog-heading"><h2>필기·확대·녹음</h2><button type="button" id="notebook-settings-close">닫기</button></div><section><h3>필기</h3><label class="notebook-check"><input id="notebook-finger" type="checkbox"> 손가락으로 필기하기</label><p>끄면 손가락은 본문 이동에 사용하고, 브라우저가 펜으로 전달하는 Apple Pencil 입력은 유지합니다. 이동 모드에서는 펜도 필기하지 않습니다.</p><p>지우개는 <b>0.1초 이상 누른 뒤</b> 닿은 선 한 획을 지웁니다. 짧은 탭은 지우지 않습니다.</p><details><summary>Apple Pencil 몸통 두 번 탭</summary><p>현재 웹사이트에서 이 몸통 동작을 받는 지원 경로를 확인하지 못했습니다. 펜·지우개 버튼으로 전환해 주세요. 화면을 두 번 두드리는 동작으로 대신 처리하지 않습니다.</p><p><a href="https://developer.apple.com/documentation/uikit/uipencilinteraction" target="_blank" rel="noopener">Apple의 네이티브 Pencil 동작 문서</a></p></details></section><section><h3>확대·축소</h3><div class="notebook-actions"><button type="button" id="notebook-zoom-out" aria-label="본문 축소">−</button><output id="notebook-zoom-label">100%</output><button type="button" id="notebook-zoom-in" aria-label="본문 확대">＋</button><button type="button" id="notebook-zoom-reset">100%로</button></div><p>75~200%로 확대·축소합니다. 확대된 본문은 이동 모드에서 좌우로도 움직일 수 있습니다.</p></section><section><h3>도구 막대</h3><label>고정 위치<select id="notebook-position">${positions.map(([id,t])=>`<option value="${id}">${t}</option>`).join('')}</select></label><p>선택한 9곳으로만 옮깁니다. 자유롭게 끄는 이동은 하지 않습니다.</p><button type="button" id="notebook-hide-tools">도구 막대 숨기기</button><small>숨겨도 ‘도구 표시’ 버튼으로 다시 열 수 있습니다.</small></section><section id="notebook-audio"></section><p id="notebook-settings-status" role="status"></p>`;document.body.append(panel);
function activate(button,fn){let touched=-1000;button.onclick=e=>{if(e.detail>0&&performance.now()-touched<600)return;fn(e);};button.addEventListener('pointerup',e=>{if(e.pointerType!=='mouse'){e.preventDefault();touched=performance.now();button.click();}});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(settings));}catch{panel.querySelector('#notebook-settings-status').textContent='설정을 저장하지 못했습니다. 이 화면에서의 변경은 적용됩니다.';}}
function position(){bar.dataset.dock=settings.position;bar.hidden=settings.hidden;reveal.hidden=!settings.hidden;}
function zoom(){const t=window.Notebook.getTarget();if(!t)return;let wrapper=t.parentElement;if(!wrapper.classList.contains('notebook-zoom-scroll')){wrapper=document.createElement('div');wrapper.className='notebook-zoom-scroll';t.before(wrapper);wrapper.append(t);}const w=Math.min(wrapper.clientWidth,isNaN(parseFloat(getComputedStyle(t).maxWidth))?wrapper.clientWidth:900);const width=Math.max(100,w)+'px';if(t.style.width!==width)t.style.width=width;t.style.maxWidth='none';t.style.zoom=String(settings.zoom);t.dataset.zoom=settings.zoom;window.dispatchEvent(new Event('resize'));}
function apply(){window.Notebook.setFingerEnabled(settings.finger);position();zoom();panel.querySelector('#notebook-finger').checked=settings.finger;panel.querySelector('#notebook-position').value=settings.position;panel.querySelector('#notebook-zoom-label').value=Math.round(settings.zoom*100)+'%';panel.querySelector('#notebook-zoom-out').disabled=settings.zoom<=.75;panel.querySelector('#notebook-zoom-in').disabled=settings.zoom>=2;}
activate(open,()=>{apply();window.StudyAudio.mount(panel.querySelector('#notebook-audio'));panel.showModal();});activate(reveal,()=>{settings.hidden=false;save();position();});activate(panel.querySelector('#notebook-settings-close'),()=>panel.close());panel.addEventListener('click',e=>{if(e.target===panel)panel.close();});
panel.querySelector('#notebook-finger').onchange=e=>{settings.finger=e.target.checked;save();apply();};panel.querySelector('#notebook-position').onchange=e=>{settings.position=e.target.value;save();position();};activate(panel.querySelector('#notebook-hide-tools'),()=>{settings.hidden=true;save();position();panel.close();});
for(const [id,delta]of [['out',-.25],['in',.25],['reset',0]])activate(panel.querySelector('#notebook-zoom-'+id),()=>{settings.zoom=id==='reset'?1:Math.max(.75,Math.min(2,settings.zoom+delta));save();apply();});
window.addEventListener('notebook-pagechange',()=>{requestAnimationFrame(()=>{zoom();});});let resizing=false;window.addEventListener('resize',()=>{if(resizing)return;resizing=true;requestAnimationFrame(()=>{resizing=false;const t=window.Notebook.getTarget(),w=t?.parentElement;if(w?.classList.contains('notebook-zoom-scroll')){const width=Math.max(100,Math.min(w.clientWidth,900))+'px';if(t.style.width!==width)t.style.width=width;}});});apply();
})();
